import "./Services.css";
import ServiceCard from "../components/ServiceCard";

export default function Services() {
  return (
    <div className="page">
      <h1>All Services</h1>

      <div className="service-grid">
        <ServiceCard title="Cleaning" img="/clean.jpg" />
        <ServiceCard title="Plumbing" img="/plumb.jpg" />
        <ServiceCard title="Electrician" img="/electric.jpg" />
        <ServiceCard title="Painting" img="/paint.jpg" />
      </div>
    </div>
  );
}
